for (const [name] of Object.entries(negatedFlags)) {
  // Set the literal flag name to false
  (out as any)[name] = false;

  // Resolve the main option for this negated flag
  const mainOption = aliasToMain.get(name);
  if (mainOption) {
    // The negated name is an alias, so set the main option to false
    (out as any)[mainOption] = false;

    // Also set all other aliases of this main option to false
    const aliases = mainToAliases.get(mainOption) || [];
    for (const alias of aliases) {
      (out as any)[alias] = false;
    }
  } else {
    // The negated name is the main option itself, so set all its aliases to false
    const aliases = mainToAliases.get(name) || [];
    for (const alias of aliases) {
      (out as any)[alias] = false;
